window.RP_SESSION={"id":"S-201ef3c1dce7","messages":[{"id":"RP-0219521","time":"2026-08-09T16:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"벌레가 낮게 난다. 꿉꿉한 습기가 하나 둘 피부에 달라붙었다.","characters":["P-c93f55c91873"]},{"id":"RP-0219522","time":"2026-08-09T16:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"주변 공기에 습기가 차기 시작했다. 머잖아 비가 쏟아질 지도 모른다. 그런 생각이 든 델타인은 하늘 위를 올려다보았다.","characters":["P-c93f55c91873"]},{"id":"RP-0219523","time":"2026-08-09T16:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아무렴, 저 먼 곳에서 비를 머금은 답답한 빛깔의 구름떼가 몰려오고 있었다.","characters":["P-c93f55c91873"]},{"id":"RP-0219524","time":"2026-08-09T16:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!어둠","characters":["P-c93f55c91873"]},{"id":"RP-0219525","time":"2026-08-09T16:56:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 어둠 판정 :\n[6, 3, 2] + [3, 6, 5]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-0219526","time":"2026-08-09T16:57:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"또 머챈트 누님에게 한 소리 듣기 전에 널어놓은 빨래들부터 모조리 걷었다. 물론 촉수들이 일부분 도와준 것은 비밀이다.","characters":["P-c93f55c91873"]},{"id":"RP-0219528","time":"2026-08-09T16:59:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이어서 대장간 바깥 쪽에 위치한 모루를 미리 안쪽에 끌어다놓고… 그러고보니 부엥 씨가 없네? 요새 뭘하고 계신 걸까?","characters":["P-c93f55c91873"]},{"id":"RP-0219529","time":"2026-08-09T17:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"흠, 죽었나? 아니, 예의없이. 죽으셨나? 아무튼 훈련장의 허수아비들과 나무로 만든 무기들도 물을 머금지 않도록 볏짚을 덮어두었다.","characters":["P-c93f55c91873"]},{"id":"RP-0219530","time":"2026-08-09T17:01:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-c93f55c91873"]},{"id":"RP-0219531","time":"2026-08-09T17:01:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 힘 판정 :\n[2] + [-1] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0219532","time":"2026-08-09T17:02:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"쌓아놓은 장작들이 비에 맞지 않게 나르다가…\n\n\"크아악!\"","characters":["P-c93f55c91873"]},{"id":"RP-0219533","time":"2026-08-09T17:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0219534","time":"2026-08-09T17:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-c93f55c91873"]},{"id":"RP-0219535","time":"2026-08-09T17:04:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 체력 판정 :\n[11] + [0] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0219536","time":"2026-08-09T17:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0219537","time":"2026-08-09T17:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"머리 쪽으로 한바퀴 굴러서… 다시 앉았다?","characters":["P-c93f55c91873"]},{"id":"RP-0219538","time":"2026-08-09T17:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"나, 사실 곡예에 재능이 있던 건가?\"","characters":["P-c93f55c91873"]},{"id":"RP-0219539","time":"2026-08-09T17:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그러나 이미 엎질러진 장작들. 아침 이슬에 살짝 젖은 풀과 흙에 못 쓰게 됐을지도.","characters":["P-c93f55c91873"]},{"id":"RP-0219540","time":"2026-08-09T17:22:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0219541","time":"2026-08-09T17:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인의 머리 속에서 문득 처음 스텔라와의 대면이 떠올랐다.\n\n\"…어, 흠, 흠. 델타인 씨, 가진 재주가 뭐라고 하셨죠?\"\n\n그 질문에 델타인은 이를 드러내며 씩 웃어보였더랬다. 벌린 입술 사이로 송곳니가 뾰족하게 빛났다.\n\n\"어지간한 잡일은 다 할 줄 알아요! 그래도 제일 잘하는 걸 묻는다면 역시 장작패기죠.\"\n\"어, 그런 걸 물어본 건 아닌데. 뭐, 좋아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0219542","time":"2026-08-09T17:32:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그러고보면 그날도 하늘에 우중충한 먹구름이 끼어 있었다. 그리고…….","characters":["P-c93f55c91873"]},{"id":"RP-0219543","time":"2026-08-09T17:32:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-c93f55c91873"]},{"id":"RP-0219544","time":"2026-08-09T17:32:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 지능 판정 :\n[5] + [4] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0219545","time":"2026-08-09T17:33:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"가방! 분명 등에 테론 씨의 등딱지만큼이나 큰 가방을 매고 있었다.","characters":["P-c93f55c91873"]},{"id":"RP-0219546","time":"2026-08-09T17:33:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어라, 내가 그걸 어디 뒀더라?\"","characters":["P-c93f55c91873"]},{"id":"RP-0219547","time":"2026-08-09T17:34:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"…….","characters":["P-c93f55c91873"]},{"id":"RP-0219548","time":"2026-08-09T17:34:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"……?","characters":["P-c93f55c91873"]},{"id":"RP-0219549","time":"2026-08-09T17:34:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"내가 가방에 뭘 넣고 왔더라?","characters":["P-c93f55c91873"]},{"id":"RP-0219550","time":"2026-08-09T17:35:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-0219551","time":"2026-08-09T17:35:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
